(function (){'use strict';if (document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initEditorFormIntegration);}else{initEditorFormIntegration();}function initEditorFormIntegration(){const forms=document.querySelectorAll('form');forms.forEach((form,formIndex)=>{form.addEventListener('submit',function (e){const editorMounts=form.querySelectorAll('.pro-editor-mount');editorMounts.forEach((mount,mountIndex)=>{const editorArea=mount.querySelector('.pro-editor-content');if (!editorArea){console.warn(`[Editor Form Integration] No editor area found in mount ${mountIndex}`);return;}const fieldName=mount.getAttribute('data-field-name');if (!fieldName){console.warn(`[Editor Form Integration] No field name found in mount ${mountIndex}`);return;}const content=editorArea.innerHTML;const hiddenTextarea=mount.querySelector('textarea[style*="display:none"]');if (hiddenTextarea){hiddenTextarea.value=content;hiddenTextarea.name=fieldName;}else{console.warn(`[Editor Form Integration] No hidden textarea found in mount ${mountIndex}`);}const formField=form.querySelector(`textarea[name="${fieldName}"]`);if (formField&&formField!==hiddenTextarea){formField.value=content;}});},false);});setInterval(syncAllEditors,3000);}function syncAllEditors(){const editorMounts=document.querySelectorAll('.pro-editor-mount');editorMounts.forEach(mount=>{const editorArea=mount.querySelector('.pro-editor-content');const hiddenTextarea=mount.querySelector('textarea[style*="display:none"]');if (editorArea&&hiddenTextarea){const content=editorArea.innerHTML;if (hiddenTextarea.value!==content){hiddenTextarea.value=content;}}});}})();